"""Calibrated compiler-boundary selection for forward attention providers."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path


@dataclass(frozen=True)
class DenseUsedKBackendRates:
    """Measured service rates for one dense used-K compiler boundary."""

    native_fixed_us: float
    native_tflops: float
    sdpa_fixed_us: float
    sdpa_tflops: float
    decision_uncertainty_us: float
    provenance: str

    def __post_init__(self) -> None:
        positive = (
            self.native_tflops,
            self.sdpa_tflops,
            self.decision_uncertainty_us,
        )
        if any(value <= 0.0 for value in positive):
            raise ValueError("attention backend rates and uncertainty must be positive")
        if self.native_fixed_us < 0.0 or self.sdpa_fixed_us < 0.0:
            raise ValueError("attention backend fixed service must be non-negative")
        if not self.provenance:
            raise ValueError("attention backend calibration needs provenance")

    @classmethod
    def from_dict(cls, values: dict[str, object]) -> "DenseUsedKBackendRates":
        return cls(
            native_fixed_us=float(values["native_fixed_us"]),
            native_tflops=float(values["native_tflops"]),
            sdpa_fixed_us=float(values["sdpa_fixed_us"]),
            sdpa_tflops=float(values["sdpa_tflops"]),
            decision_uncertainty_us=float(values["decision_uncertainty_us"]),
            provenance=str(values["provenance"]),
        )


def dense_attention_flops(
    *,
    batch_size: int,
    q_len: int,
    kv_len: int,
    q_heads: int,
    head_dim: int,
) -> int:
    """QK plus probability-V FLOPs for a dense attention demand."""

    dimensions = (batch_size, q_len, kv_len, q_heads, head_dim)
    if any(isinstance(value, bool) or int(value) <= 0 for value in dimensions):
        raise ValueError("dense attention pricing dimensions must be positive integers")
    return 4 * int(batch_size) * int(q_len) * int(kv_len) * int(q_heads) * int(head_dim)


def _service_us(*, fixed_us: float, tflops: float, flops: int) -> float:
    return float(fixed_us) + int(flops) / (float(tflops) * 1.0e6)


def dense_used_k_native_wins(
    rates: DenseUsedKBackendRates,
    *,
    batch_size: int,
    q_len: int,
    kv_len: int,
    q_heads: int,
    head_dim: int,
) -> bool:
    """Select native only when its conservative bound beats traceable SDPA."""

    flops = dense_attention_flops(
        batch_size=batch_size,
        q_len=q_len,
        kv_len=kv_len,
        q_heads=q_heads,
        head_dim=head_dim,
    )
    native_us = _service_us(
        fixed_us=rates.native_fixed_us,
        tflops=rates.native_tflops,
        flops=flops,
    )
    sdpa_us = _service_us(
        fixed_us=rates.sdpa_fixed_us,
        tflops=rates.sdpa_tflops,
        flops=flops,
    )
    uncertainty = rates.decision_uncertainty_us
    return native_us + uncertainty < sdpa_us - uncertainty


@lru_cache(maxsize=None)
def load_dense_used_k_backend_rates(
    gpu_name_key: str,
) -> DenseUsedKBackendRates | None:
    path = (
        Path(__file__).resolve().parents[2]
        / "configs"
        / f"flash_attn_backend_{gpu_name_key}.json"
    )
    try:
        document = json.loads(path.read_text())
    except FileNotFoundError:
        return None
    if document.get("schema_version") != 1:
        raise ValueError(f"unsupported attention backend calibration schema in {path}")
    return DenseUsedKBackendRates.from_dict(document["dense_used_k"])


__all__ = [
    "DenseUsedKBackendRates",
    "dense_attention_flops",
    "dense_used_k_native_wins",
    "load_dense_used_k_backend_rates",
]
